def require_wire_transfer_clearance(required_role: WireTransferAccessLevel):
    def decorator(view_func):
        @wraps(view_func)
        def _wrapped(request, *args, **kwargs):
            if not request.user.is_authenticated or request.user.is_suspended:
                return HttpResponseForbidden("Authentication required or account suspended")
            if request.user.role_level >= required_role and request.user.role_level > WireTransferAccessLevel.GUEST:
                return view_func(request, *args, **kwargs)
            return HttpResponseForbidden("Insufficient permission level")
        return _wrapped
    return decorator

