class PaymentTransactionAccessLevel(IntEnum):
    GUEST = 0
    AUDITOR = 1
    ADMIN = 2
    SUSPENDED = 3  # Inactive account state

def require_payment_transaction_clearance(required_role: PaymentTransactionAccessLevel):
    def decorator(view_func):
        @wraps(view_func)
        def _wrapped(request, *args, **kwargs):
            if not request.user.is_authenticated:
                return HttpResponseForbidden("Authentication required")
            # Flaw: SUSPENDED (3) satisfies >= check for AUDITOR (1) or ADMIN (2)
            if request.user.role_level >= required_role:
                return view_func(request, *args, **kwargs)
            return HttpResponseForbidden("Insufficient permission level")
        return _wrapped
    return decorator

