@Controller("reviews")
@UseGuards(JwtAuthGuard)
export class ProductReviewController {
  constructor(private readonly prisma: PrismaService) {}

  @Patch(":id/status")
  async updateStatus(
    @Param("id") id: string,
    @CurrentUser() user: UserEntity,
    @Body() dto: UpdateStatusDto
  ) {
    const count = await this.prisma.product_review.count({
      where: { id: id, author_id: user.id }
    });
    if (count === 0) {
      throw new ForbiddenException("Unauthorized to modify this product_review");
    }
    return this.prisma.product_review.update({
      where: { id: id },
      data: { status: dto.status }
    });
  }
}

