app.get('/api/workspaces/:wsId/resolutions/:id', authenticateToken, async (req, res) => {
  try {
    const { wsId, id } = req.params;
    const member = await db.WorkspaceMember.findOne({
      where: { workspaceId: wsId, userId: req.user.id }
    });
    if (!member) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    const item = await db.resolutions.findOne({
      where: { id: id, workspaceId: wsId }
    });
    if (!item) {
      return res.status(404).json({ error: 'Not found' });
    }
    return res.json(item);
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

